// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/info", wrapper.GetInfo)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/login", wrapper.Login)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/dashboard", wrapper.GetDashboard)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/workouts", wrapper.StartWorkout)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/workouts/{id}", wrapper.AbandonWorkout)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/workouts/{id}", wrapper.GetWorkout)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/workouts/{id}/sets/{idx}", wrapper.UndoSet)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/workouts/{id}/sets/{idx}", wrapper.LogSet)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/workouts/{id}/finish", wrapper.FinishWorkout)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/plates", wrapper.GetPlates)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/history", wrapper.GetHistory)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/lifts/{slug}", wrapper.GetLift)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/lifts/{slug}/estimates", wrapper.AddPastEstimate)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/lifts/{slug}/estimates/{id}", wrapper.DeletePastEstimate)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/settings", wrapper.GetSettings)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/settings", wrapper.SaveSettings)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/training-maxes", wrapper.SetTrainingMax)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/tm-review", wrapper.AcceptReview)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/tm-tests/{id}", wrapper.DecideTMTest)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/skip-cycle", wrapper.SkipCycle)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/setup", wrapper.GetSetup)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/setup", wrapper.SaveSetup)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/setup/position", wrapper.GetSetupPosition)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/setup/history/{cycle}", wrapper.GetSetupHistory)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/setup/history/{cycle}", wrapper.SaveSetupHistory)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/backup", wrapper.GetBackup)

	return m
}

