// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetBackup Download the database
	// (GET /backup)
	GetBackup(ctx context.Context, request GetBackupRequestObject) (GetBackupResponseObject, error)
	// GetDashboard The Today screen
	// (GET /dashboard)
	GetDashboard(ctx context.Context, request GetDashboardRequestObject) (GetDashboardResponseObject, error)
	// GetHistory The history list
	// (GET /history)
	GetHistory(ctx context.Context, request GetHistoryRequestObject) (GetHistoryResponseObject, error)
	// GetInfo Which API and server build this is
	// (GET /info)
	GetInfo(ctx context.Context, request GetInfoRequestObject) (GetInfoResponseObject, error)
	// GetLift A lift's progress
	// (GET /lifts/{slug})
	GetLift(ctx context.Context, request GetLiftRequestObject) (GetLiftResponseObject, error)
	// AddPastEstimate Add an estimate from before the app
	// (POST /lifts/{slug}/estimates)
	AddPastEstimate(ctx context.Context, request AddPastEstimateRequestObject) (AddPastEstimateResponseObject, error)
	// DeletePastEstimate Delete an estimate from before the app
	// (DELETE /lifts/{slug}/estimates/{id})
	DeletePastEstimate(ctx context.Context, request DeletePastEstimateRequestObject) (DeletePastEstimateResponseObject, error)
	// Login Exchange the password for a session token
	// (POST /login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// GetPlates How to load the bar for a weight
	// (GET /plates)
	GetPlates(ctx context.Context, request GetPlatesRequestObject) (GetPlatesResponseObject, error)
	// GetSettings The settings screen
	// (GET /settings)
	GetSettings(ctx context.Context, request GetSettingsRequestObject) (GetSettingsResponseObject, error)
	// SaveSettings Change the settings
	// (PUT /settings)
	SaveSettings(ctx context.Context, request SaveSettingsRequestObject) (SaveSettingsResponseObject, error)
	// GetSetup The first-run screen where training maxes are entered
	// (GET /setup)
	GetSetup(ctx context.Context, request GetSetupRequestObject) (GetSetupResponseObject, error)
	// SaveSetup Record the first training maxes
	// (PUT /setup)
	SaveSetup(ctx context.Context, request SaveSetupRequestObject) (SaveSetupResponseObject, error)
	// GetSetupHistory The checklist of sessions already done in a cycle
	// (GET /setup/history/{cycle})
	GetSetupHistory(ctx context.Context, request GetSetupHistoryRequestObject) (GetSetupHistoryResponseObject, error)
	// SaveSetupHistory Join the block at a cycle, with the sessions of it already done
	// (PUT /setup/history/{cycle})
	SaveSetupHistory(ctx context.Context, request SaveSetupHistoryRequestObject) (SaveSetupHistoryResponseObject, error)
	// GetSetupPosition Ask which cycle the user is on
	// (GET /setup/position)
	GetSetupPosition(ctx context.Context, request GetSetupPositionRequestObject) (GetSetupPositionResponseObject, error)
	// SkipCycle Pass on an optional cycle before its first session
	// (POST /skip-cycle)
	SkipCycle(ctx context.Context, request SkipCycleRequestObject) (SkipCycleResponseObject, error)
	// AcceptReview Accept the block review
	// (POST /tm-review)
	AcceptReview(ctx context.Context, request AcceptReviewRequestObject) (AcceptReviewResponseObject, error)
	// DecideTMTest Settle a failed TM test
	// (POST /tm-tests/{id})
	DecideTMTest(ctx context.Context, request DecideTMTestRequestObject) (DecideTMTestResponseObject, error)
	// SetTrainingMax Change one lift's training max
	// (POST /training-maxes)
	SetTrainingMax(ctx context.Context, request SetTrainingMaxRequestObject) (SetTrainingMaxResponseObject, error)
	// StartWorkout Start the next session, or resume the one in progress
	// (POST /workouts)
	StartWorkout(ctx context.Context, request StartWorkoutRequestObject) (StartWorkoutResponseObject, error)
	// AbandonWorkout Remove a session started by mistake
	// (DELETE /workouts/{id})
	AbandonWorkout(ctx context.Context, request AbandonWorkoutRequestObject) (AbandonWorkoutResponseObject, error)
	// GetWorkout A session, in progress or completed
	// (GET /workouts/{id})
	GetWorkout(ctx context.Context, request GetWorkoutRequestObject) (GetWorkoutResponseObject, error)
	// FinishWorkout Mark a session complete
	// (POST /workouts/{id}/finish)
	FinishWorkout(ctx context.Context, request FinishWorkoutRequestObject) (FinishWorkoutResponseObject, error)
	// UndoSet Clear a logged set
	// (DELETE /workouts/{id}/sets/{idx})
	UndoSet(ctx context.Context, request UndoSetRequestObject) (UndoSetResponseObject, error)
	// LogSet Log the reps done on a set, and the weight if it changed
	// (PUT /workouts/{id}/sets/{idx})
	LogSet(ctx context.Context, request LogSetRequestObject) (LogSetResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

