// UndoSet operation middleware
func (sh *strictHandler) UndoSet(w http.ResponseWriter, r *http.Request, id WorkoutID, idx SetIdx) {
	var request UndoSetRequestObject

	request.ID = id
	request.Idx = idx

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.UndoSet(ctx, request.(UndoSetRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "UndoSet")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(UndoSetResponseObject); ok {
		if err := validResponse.VisitUndoSetResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

// LogSet operation middleware
func (sh *strictHandler) LogSet(w http.ResponseWriter, r *http.Request, id WorkoutID, idx SetIdx) {
	var request LogSetRequestObject

	request.ID = id
	request.Idx = idx

	var body LogSetJSONRequestBody
	if err := runtime.BindJSONBody(r, &body); err != nil {
		sh.options.RequestErrorHandlerFunc(w, r, fmt.Errorf("can't decode JSON body: %w", err))
		return
	}
	request.Body = &body

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.LogSet(ctx, request.(LogSetRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "LogSet")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(LogSetResponseObject); ok {
		if err := validResponse.VisitLogSetResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

